   857              && key_len == types[i].key_len &&
   858              !strncmp(key, types[i].key, key_len)) {
   859
   860              casted = FLB_TRUE;
   861
   862              msgpack_pack_str(pck, key_len);
   863              msgpack_pack_str_body(pck, key, key_len);
   864
   865              switch (types[i].type) {
   866              case FLB_PARSER_TYPE_INT:
   867                  {
   868                      long long lval;
   869
   870                      /* msgpack char is not null terminated.
   871                         So make a temporary copy.
   872                       */
   873                      tmp_str = flb_strndup(val, val_len);
   874                      lval = atoll(tmp_str);
   875                      flb_free(tmp_str);
   876                      msgpack_pack_int64(pck, lval);
   877                  }
   878                  break;
   879              case FLB_PARSER_TYPE_HEX:
   880                  {
   881                      unsigned long long lval;
   882                      tmp_str = flb_strndup(val, val_len);
   883                      lval = strtoull(tmp_str, NULL, 16);
   884                      flb_free(tmp_str);
   885                      msgpack_pack_uint64(pck, lval);
   886                  }
   887                  break;
   888
   889              case FLB_PARSER_TYPE_FLOAT:
   890                  {
   891                      double dval;
   892                      tmp_str = flb_strndup(val, val_len);
   893                      dval = atof(tmp_str);
   894                      flb_free(tmp_str);
   895                      msgpack_pack_double(pck, dval);
   896                  }
   897                  break;
   898              case FLB_PARSER_TYPE_BOOL:
   899                  if (!strncasecmp(val, "true", 4)) {
   900                      msgpack_pack_true(pck);
        dec_rule->backend = (int)(data[0] % 0x04);
        MOVE_INPUT(1);
        dec_rule->action = (int)data[0] % 0x03;
        mk_list_add(&dec_rule->_head, &dec->rules);

        if (GET_MOD_EQ(2,1)) {
            struct flb_parser_dec_rule *dec_rule2 = malloc(sizeof(struct flb_parser_dec_rule));
            dec_rule2->type = (int)(data[0] % 0x02);
            MOVE_INPUT(1);
            dec_rule2->backend = (int)(data[0] % 0x04);
            MOVE_INPUT(1);
            dec_rule->action = (int)data[0] % 0x03;
            mk_list_add(&dec_rule2->_head, &dec->rules);
